import { defineConfig, devices } from '@playwright/test';

/**
 * Tests run against the full stack started with `docker compose up`.
 * E2E_BASE_URL points at the web application (default: the Compose `web` service).
 */
const baseURL = process.env['E2E_BASE_URL'] ?? 'http://localhost:4200';

export default defineConfig({
  testDir: './tests',
  fullyParallel: true,
  forbidOnly: !!process.env['CI'],
  retries: process.env['CI'] ? 2 : 0,
  reporter: [['list'], ['html', { open: 'never' }]],
  use: {
    baseURL,
    trace: 'on-first-retry',
  },
  projects: [
    { name: 'mobile', use: { ...devices['Desktop Chrome'], viewport: { width: 375, height: 812 } } },
    { name: 'desktop', use: { ...devices['Desktop Chrome'], viewport: { width: 1280, height: 800 } } },
  ],
});
EOF
cat > e2e/tests/fixtures.ts <<'EOF'
import AxeBuilder from '@axe-core/playwright';
import { test as base, expect } from '@playwright/test';

/** WCAG 2.2 AA rule tags checked on every scanned page (docs/design.md). */
const WCAG_TAGS = ['wcag2a', 'wcag2aa', 'wcag21a', 'wcag21aa', 'wcag22aa'];

type Fixtures = {
  /** Runs an axe scan of the current page and fails the test on any violation. */
  expectNoAxeViolations: () => Promise<void>;
};

export const test = base.extend<Fixtures>({
  expectNoAxeViolations: async ({ page }, use) => {
    await use(async () => {
      const results = await new AxeBuilder({ page }).withTags(WCAG_TAGS).analyze();
      expect(results.violations).toEqual([]);
    });
  },
});

export { expect };
EOF
